--
-- Name: analytics_project_summary; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_project_summary AS
 SELECT id AS project_id,
    COALESCE(project_code, code) AS project_code,
    name AS project_name,
    entity_code,
    COALESCE(NULLIF((status)::text, ''::text), 'ACTIVE'::text) AS status,
    COALESCE(contract_amount, contract_total) AS contract_amount,
    start_date,
    expected_end_date,
    COALESCE(NULLIF((location)::text, ''::text), (city)::text) AS location,
    project_type,
    external_system,
    external_project_id,
    CURRENT_TIMESTAMP AS calculated_at
   FROM public.projects p;


