--
-- Name: analytics_cashflow; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_cashflow AS
 WITH cf AS (
         SELECT cashflows.project_id,
            sum(
                CASE
                    WHEN ((cashflows.direction)::text = 'in'::text) THEN cashflows.amount
                    ELSE (0)::numeric
                END) AS cash_inflow,
            sum(
                CASE
                    WHEN ((cashflows.direction)::text = 'out'::text) THEN cashflows.amount
                    ELSE (0)::numeric
                END) AS cash_outflow
           FROM public.cashflows
          GROUP BY cashflows.project_id
        )
 SELECT p.project_id,
    p.project_code,
    p.project_name,
    cf.cash_inflow,
    cf.cash_outflow,
        CASE
            WHEN ((cf.cash_inflow IS NULL) AND (cf.cash_outflow IS NULL)) THEN NULL::numeric
            ELSE (COALESCE(cf.cash_inflow, (0)::numeric) - COALESCE(cf.cash_outflow, (0)::numeric))
        END AS net_cashflow,
    NULL::numeric AS cash_gap_30d,
    CURRENT_TIMESTAMP AS calculated_at
   FROM (public.analytics_project_summary p
     LEFT JOIN cf ON ((cf.project_id = p.project_id)));


ALTER VIEW public.analytics_cashflow OWNER TO yvoche;

