--
-- Name: analytics_cost; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_cost AS
 WITH a AS (
         SELECT real_costs.project_id,
            sum(real_costs.amount) AS actual_cost
           FROM public.real_costs
          GROUP BY real_costs.project_id
        ), b AS (
         SELECT budgets.project_id,
            sum(budgets.amount) AS budget_cost
           FROM public.budgets
          GROUP BY budgets.project_id
        )
 SELECT p.project_id,
    p.project_code,
    p.project_name,
    a.actual_cost,
    b.budget_cost,
        CASE
            WHEN ((a.actual_cost IS NULL) OR (b.budget_cost IS NULL)) THEN NULL::numeric
            ELSE (a.actual_cost - b.budget_cost)
        END AS cost_variance,
        CASE
            WHEN ((b.budget_cost > (0)::numeric) AND (a.actual_cost IS NOT NULL)) THEN ((a.actual_cost - b.budget_cost) / b.budget_cost)
            ELSE NULL::numeric
        END AS cost_variance_rate,
        CASE
            WHEN ((a.actual_cost > (0)::numeric) AND (b.budget_cost IS NOT NULL)) THEN (b.budget_cost / a.actual_cost)
            ELSE NULL::numeric
        END AS cpi,
    CURRENT_TIMESTAMP AS calculated_at
   FROM ((public.analytics_project_summary p
     LEFT JOIN a ON ((a.project_id = p.project_id)))
     LEFT JOIN b ON ((b.project_id = p.project_id)));


ALTER VIEW public.analytics_cost OWNER TO yvoche;

