--
-- Name: analytics_project_profit; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_project_profit AS
 WITH pr AS (
         SELECT progress.project_id,
            sum(progress.recognized_revenue) AS recognized_revenue,
            sum(progress.collection) AS collected_amount
           FROM public.progress
          GROUP BY progress.project_id
        ), rc AS (
         SELECT real_costs.project_id,
            sum(real_costs.amount) AS real_project_cost
           FROM public.real_costs
          GROUP BY real_costs.project_id
        )
 SELECT p.project_id,
    p.project_code,
    p.project_name,
    p.entity_code,
    p.contract_amount,
    pr.recognized_revenue,
    rc.real_project_cost,
        CASE
            WHEN ((pr.recognized_revenue IS NULL) OR (rc.real_project_cost IS NULL)) THEN NULL::numeric
            ELSE (pr.recognized_revenue - rc.real_project_cost)
        END AS real_profit,
    pr.collected_amount,
        CASE
            WHEN (pr.recognized_revenue > (0)::numeric) THEN (pr.collected_amount / pr.recognized_revenue)
            ELSE NULL::numeric
        END AS collection_rate,
        CASE
            WHEN ((pr.recognized_revenue IS NULL) OR (pr.collected_amount IS NULL)) THEN NULL::numeric
            ELSE (pr.recognized_revenue - pr.collected_amount)
        END AS unpaid_amount,
    CURRENT_TIMESTAMP AS calculated_at
   FROM ((public.analytics_project_summary p
     LEFT JOIN pr ON ((pr.project_id = p.project_id)))
     LEFT JOIN rc ON ((rc.project_id = p.project_id)));


ALTER VIEW public.analytics_project_profit OWNER TO yvoche;

--
-- Name: analytics_eac; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_eac AS
 SELECT p.project_id,
    p.project_code,
    p.project_name,
    p.contract_amount,
    pp.recognized_revenue,
    pp.real_project_cost AS actual_cost,
        CASE
            WHEN ((p.contract_amount > (0)::numeric) AND (pp.recognized_revenue > (0)::numeric) AND (pp.real_project_cost IS NOT NULL)) THEN (pp.real_project_cost / (pp.recognized_revenue / p.contract_amount))
            ELSE NULL::numeric
        END AS eac_cost,
    p.contract_amount AS eac_revenue,
        CASE
            WHEN ((p.contract_amount > (0)::numeric) AND (pp.recognized_revenue > (0)::numeric) AND (pp.real_project_cost IS NOT NULL)) THEN (p.contract_amount - (pp.real_project_cost / (pp.recognized_revenue / p.contract_amount)))
            ELSE NULL::numeric
        END AS eac_profit,
        CASE
            WHEN ((p.contract_amount > (0)::numeric) AND (pp.recognized_revenue > (0)::numeric) AND (pp.real_project_cost IS NOT NULL)) THEN ((p.contract_amount - (pp.real_project_cost / (pp.recognized_revenue / p.contract_amount))) / p.contract_amount)
            ELSE NULL::numeric
        END AS eac_margin,
    'management_estimate_revenue_progress'::text AS eac_method,
    CURRENT_TIMESTAMP AS calculated_at
   FROM (public.analytics_project_summary p
     LEFT JOIN public.analytics_project_profit pp USING (project_id, project_code, project_name, contract_amount));


ALTER VIEW public.analytics_eac OWNER TO yvoche;

