--
-- Name: analytics_tax; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_tax AS
 WITH iv AS (
         SELECT invoices.project_id,
            sum(
                CASE
                    WHEN ((invoices.direction)::text = 'out'::text) THEN invoices.vat
                    ELSE (0)::numeric
                END) AS output_vat,
            sum(
                CASE
                    WHEN (((invoices.direction)::text = 'in'::text) AND invoices.deductible) THEN invoices.vat
                    ELSE (0)::numeric
                END) AS input_vat
           FROM public.invoices
          GROUP BY invoices.project_id
        )
 SELECT p.project_id,
    p.project_code,
    p.project_name,
    p.entity_code,
    iv.output_vat,
    iv.input_vat,
        CASE
            WHEN ((iv.output_vat IS NULL) AND (iv.input_vat IS NULL)) THEN NULL::numeric
            ELSE GREATEST((COALESCE(iv.output_vat, (0)::numeric) - COALESCE(iv.input_vat, (0)::numeric)), (0)::numeric)
        END AS vat_payable,
    NULL::numeric AS income_tax_estimate,
    NULL::numeric AS surcharge_estimate,
    NULL::numeric AS tax_burden_rate,
    NULL::numeric AS total_tax_burden,
    CURRENT_TIMESTAMP AS calculated_at
   FROM (public.analytics_project_summary p
     LEFT JOIN iv ON ((iv.project_id = p.project_id)));


ALTER VIEW public.analytics_tax OWNER TO yvoche;

--
-- Name: analytics_project_full; Type: VIEW; Schema: public; Owner: yvoche
--

CREATE VIEW public.analytics_project_full AS
 SELECT s.project_id,
    s.project_code,
    s.project_name,
    s.entity_code,
    s.status,
    s.contract_amount,
    s.location,
    pp.recognized_revenue,
    pp.real_project_cost,
    pp.real_profit,
    pp.collected_amount,
    pp.unpaid_amount,
    pp.collection_rate,
    e.eac_revenue,
    e.eac_cost,
    e.eac_profit,
    e.eac_margin,
    e.eac_method,
    c.cost_variance,
    cf.cash_inflow,
    cf.cash_outflow,
    cf.net_cashflow,
    cf.cash_gap_30d,
    t.output_vat,
    t.input_vat,
    t.vat_payable,
    t.tax_burden_rate,
    NULL::numeric AS health_score,
    ((pp.recognized_revenue IS NOT NULL) AND (pp.real_project_cost IS NOT NULL) AND (pp.collection_rate IS NOT NULL) AND (e.eac_profit IS NOT NULL) AND (e.eac_margin IS NOT NULL)) AS facts_available,
    CURRENT_TIMESTAMP AS calculated_at
   FROM (((((public.analytics_project_summary s
     LEFT JOIN public.analytics_project_profit pp USING (project_id))
     LEFT JOIN public.analytics_eac e USING (project_id))
     LEFT JOIN public.analytics_cost c USING (project_id))
     LEFT JOIN public.analytics_cashflow cf USING (project_id))
     LEFT JOIN public.analytics_tax t USING (project_id));


ALTER VIEW public.analytics_project_full OWNER TO yvoche;

--
